/* REGLA: PQR_RGL_getMailDetailsTotalCount (MODIFICADA)
CAMBIO: se agrega el nuevo parámetro de entrada ri!clasificadoPorFilter y su filtro correspondiente.
IMPORTANTE — agregar el RULE INPUT en la regla: Nombre: clasificadoPorFilter Tipo: Text (String) */ #"SYSTEM_SYSRULES_queryRecordType_v4"( recordType: #"urn:appian:record-type:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4", fields: { #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/9aa2ba60-e02c-4792-aa94-797e7da3ca0c" }, filters: #"SYSTEM_SYSRULES_queryLogicalExpression"( operator: "AND", filters: { #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/a3c256a0-ded5-4f3d-9686-fefe4e4057b0", operator: "includes", value: ri!fromFilter, applyWhen: a!isInText(ri!fromFilter, "@") ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/a5ffe5fa-7b2c-47d9-965d-a033f8c66349", operator: "includes", value: ri!fromFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/e3f6788e-3427-4637-83cd-ea0bb884ec26", operator: "includes", value: ri!toFilter, applyWhen: a!isInText(ri!toFilter, "@") ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/64787dc1-052b-41fb-b443-d6f2a6ce90d8", operator: "includes", value: ri!toFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/6beb40ad-2319-4d5e-bff8-f854494ced72", operator: "includes", value: ri!subjectFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/098ce992-4c7d-48a6-8122-1e13a1ebc8f4", operator: "includes", value: ri!bodyFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/683d1f87-94d9-4959-be82-82f0144b185b", operator: "in", value: ri!estadoFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/415542e0-75b2-490b-ac5b-409392adb155", operator: ">=", value: ri!fromDateFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/415542e0-75b2-490b-ac5b-409392adb155", operator: "<=", value: ri!toDateFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/9a87e8ad-c22d-4be9-9e7f-978503ebf910/b166a748-4a36-43a3-99a4-412a24157620", operator: "in", value: ri!tagFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/ec9444b7-7469-470e-b61a-1461c739c42e/f54d21c3-52dc-4b3b-8134-98da2e9c25a3", operator: "=", value: ri!tipoEventoFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/9a87e8ad-c22d-4be9-9e7f-978503ebf910/a93e1325-1e25-4a65-ae1c-0e9a91e1ff6f", operator: ">=", value: ri!fromConfidenceFilter ), #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/9a87e8ad-c22d-4be9-9e7f-978503ebf910/a93e1325-1e25-4a65-ae1c-0e9a91e1ff6f", operator: "<=", value: ri!toConfidenceFilter ), /* Filtro existente: usuario aprobador (usuario del evento) */ #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/ec9444b7-7469-470e-b61a-1461c739c42e/d905bb4a-e56a-417c-9504-66fbe5da37ca", operator: "=", value: ri!approbalUserFilter ), /* NUEVO: filtro clasificado por (usuario del evento de clasificación) */ #"SYSTEM_SYSRULES_queryFilter"( field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/ec9444b7-7469-470e-b61a-1461c739c42e/d905bb4a-e56a-417c-9504-66fbe5da37ca", operator: "=", value: ri!clasificadoPorFilter ) }, ignoreFiltersWithEmptyValues: true ), pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 1), fetchTotalCount: true() )
